import{_ as e,o as i,c as s,a2 as l}from"./chunks/framework.C0KMm31j.js";const t="/Nav2ArticlesSite/article-assets/2026-07-30/ros2_action_callbacks_01_comparison.png",n="/Nav2ArticlesSite/article-assets/2026-07-30/ros2_action_callbacks_02_transport.png",o="/Nav2ArticlesSite/article-assets/2026-07-30/ros2_action_callbacks_03_follow_path.png",c="/Nav2ArticlesSite/article-assets/2026-07-30/ros2_action_callbacks_04_planning.png",p="/Nav2ArticlesSite/article-assets/2026-07-30/ros2_action_callbacks_05_server.png",h="/Nav2ArticlesSite/article-assets/2026-07-30/ros2_action_callbacks_06_stale_guard.png",y=JSON.parse('{"title":"三个回调为什么到了规划器只剩两个？从 Nav2 源码拆透 ROS 2 Action","description":"同样是 rclcppaction::Client<ActionT::SendGoalOptions，为什么 navigatorcontrol.cpp 同时设置 goalresponsecallback、feedbackcallback 和 resultcallback，到了 navigatorpla","frontmatter":{"title":"三个回调为什么到了规划器只剩两个？从 Nav2 源码拆透 ROS 2 Action","description":"同样是 rclcppaction::Client<ActionT::SendGoalOptions，为什么 navigatorcontrol.cpp 同时设置 goalresponsecallback、feedbackcallback 和 resultcallback，到了 navigatorpla","date":"2026-07-30","section":"六 · ROS 2 接口与工程实践","readingTime":16,"source":"2026-07-30/ros2_action_callbacks_source_design.md","status":"published","cover":"/article-assets/2026-07-30/ros2_action_callbacks_01_comparison.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/nav2/ros2-action-callbacks-source-design"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"三个回调为什么到了规划器只剩两个？从 Nav2 源码拆透 ROS 2 Action"}],["meta",{"property":"og:description","content":"同样是 rclcppaction::Client<ActionT::SendGoalOptions，为什么 navigatorcontrol.cpp 同时设置 goalresponsecallback、feedbackcallback 和 resultcallback，到了 navigatorpla"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/nav2/ros2-action-callbacks-source-design"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-07-30/ros2_action_callbacks_01_comparison.png"}],["meta",{"property":"article:published_time","content":"2026-07-30"}],["meta",{"name":"twitter:title","content":"三个回调为什么到了规划器只剩两个？从 Nav2 源码拆透 ROS 2 Action"}],["meta",{"name":"twitter:description","content":"同样是 rclcppaction::Client<ActionT::SendGoalOptions，为什么 navigatorcontrol.cpp 同时设置 goalresponsecallback、feedbackcallback 和 resultcallback，到了 navigatorpla"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-07-30/ros2_action_callbacks_01_comparison.png"}]],"prev":{"text":"一个进程装下整套 ROS 2？从 ComponentManager 一路拆到 rcl、rmw 与进程内通信","link":"/nav2/ros2-composition-rclcpp-full-dataflow"},"next":{"text":"Nav2 为什么能随时换算法？拆解 nav2_core 的七类插件契约","link":"/nav2/nav2-core-plugin-contracts-and-dataflow"}},"headers":[],"relativePath":"nav2/ros2-action-callbacks-source-design.md","filePath":"nav2/ros2-action-callbacks-source-design.md","lastUpdated":null}'),d={name:"nav2/ros2-action-callbacks-source-design.md"};function r(k,a,g,E,u,b){return i(),s("div",null,[...a[0]||(a[0]=[l('<h1 id="三个回调为什么到了规划器只剩两个-从-nav2-源码拆透-ros-2-action" tabindex="-1">三个回调为什么到了规划器只剩两个？从 Nav2 源码拆透 ROS 2 Action <a class="header-anchor" href="#三个回调为什么到了规划器只剩两个-从-nav2-源码拆透-ros-2-action" aria-label="Permalink to &quot;三个回调为什么到了规划器只剩两个？从 Nav2 源码拆透 ROS 2 Action&quot;">​</a></h1><p>同样是 <code>rclcpp_action::Client&lt;ActionT&gt;::SendGoalOptions</code>，为什么 <code>navigator_control.cpp</code> 同时设置 <code>goal_response_callback</code>、<code>feedback_callback</code> 和 <code>result_callback</code>，到了 <code>navigator_planning.cpp</code> 却只剩下两个？</p><p>答案不是少写了一段代码，也不是 Planner Server 不支持 Action，而是两类任务对“中间过程”的需求不同。</p><p><code>FollowPath</code> 是持续执行型任务。机器人可能沿路径运行数十秒，调用方需要知道 Goal 是否被接收、当前还剩多远、机器人速度是多少，以及最终成功还是失败。因此，三个回调都有明确的数据。</p><p><code>ComputePathToPose</code>、<code>ComputePathThroughPoses</code> 和 <code>SmoothPath</code> 是有界计算型任务。调用方关心请求有没有被接受，以及最终返回哪条 Path。它们当前的 Action 接口没有定义有效的 Feedback 字段，所以不注册 <code>feedback_callback</code> 才是更准确的设计。</p><p>本文以当前 <code>navigation2</code> 源码和本机 ROS 2 Humble 的 <code>rclcpp_action</code> 头文件为依据，从这个小差异出发，完整拆开 ROS 2 Action 的客户端函数、服务端函数、五条底层通道、取消语义和异步回调防护。</p><h2 id="一、回调数量不同的直接答案" tabindex="-1">一、回调数量不同的直接答案 <a class="header-anchor" href="#一、回调数量不同的直接答案" aria-label="Permalink to &quot;一、回调数量不同的直接答案&quot;">​</a></h2><h3 id="_1-1-控制模块注册了三个回调" tabindex="-1">1.1 控制模块注册了三个回调 <a class="header-anchor" href="#_1-1-控制模块注册了三个回调" aria-label="Permalink to &quot;1.1 控制模块注册了三个回调&quot;">​</a></h3><p><code>navigator_control.cpp</code> 的 <code>sendFollowPath()</code> 构造 <code>FollowPath::Goal</code> 后，给 <code>SendGoalOptions</code> 安装三个客户端回调：</p><ul><li><code>goal_response_callback</code>：判断 Controller Server 是否接受 Goal，并保存活动 Goal Handle。</li><li><code>feedback_callback</code>：接收剩余距离和当前速度。</li><li><code>result_callback</code>：处理成功、失败和取消后的最终收口。</li></ul><p>控制任务不是“一次输入、立即输出”的计算，而是一段持续占用机器人的物理执行过程。中间反馈可以直接服务上层调度、界面显示、超时判断和固定路径 Action 的反馈转发。</p><h3 id="_1-2-规划模块只注册了两个回调" tabindex="-1">1.2 规划模块只注册了两个回调 <a class="header-anchor" href="#_1-2-规划模块只注册了两个回调" aria-label="Permalink to &quot;1.2 规划模块只注册了两个回调&quot;">​</a></h3><p><code>navigator_planning.cpp</code> 会向三个 Action 发送 Goal：</p><ul><li><code>ComputePathToPose</code>：计算当前位置到单个目标的路径。</li><li><code>ComputePathThroughPoses</code>：计算经过多个目标点的路径。</li><li><code>SmoothPath</code>：对原始 Path 做平滑处理。</li></ul><p>三个 Action 都设置 <code>goal_response_callback</code> 和 <code>result_callback</code>，但都没有设置 <code>feedback_callback</code>。原因就在对应 <code>.action</code> 文件的 Feedback 区：它们只有注释，没有任何业务字段。</p><h3 id="_1-3-判断依据是数据语义" tabindex="-1">1.3 判断依据是数据语义 <a class="header-anchor" href="#_1-3-判断依据是数据语义" aria-label="Permalink to &quot;1.3 判断依据是数据语义&quot;">​</a></h3><p><code>SendGoalOptions</code> 提供三个回调槽，不代表三个槽必须全部填写。ROS 2 Humble 中，这三个成员默认都是 <code>nullptr</code>，客户端可以按需使用。</p><p>回调数量应由以下事实决定：</p><ul><li><code>.action</code> 是否定义了有效字段。</li><li>服务端是否真的发布对应数据。</li><li>中间过程对调用方是否有决策价值。</li><li>回调是否会改变上层状态、监控或人机界面。</li></ul><p>为了让两个文件看起来对称而注册一个空 Feedback 回调，只会制造没有业务价值的调度和日志。</p><p><img src="'+t+`" alt="控制与规划的回调数量对比"></p><h2 id="二、action-为什么不能简单理解成-service" tabindex="-1">二、Action 为什么不能简单理解成 Service <a class="header-anchor" href="#二、action-为什么不能简单理解成-service" aria-label="Permalink to &quot;二、Action 为什么不能简单理解成 Service&quot;">​</a></h2><h3 id="_2-1-action-文件定义三类数据" tabindex="-1">2.1 <code>.action</code> 文件定义三类数据 <a class="header-anchor" href="#_2-1-action-文件定义三类数据" aria-label="Permalink to &quot;2.1 \`.action\` 文件定义三类数据&quot;">​</a></h3><p>一个 Action 接口由 Goal、Result 和 Feedback 三个区域组成。</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Goal</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">任务输入</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">---</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Result</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">最终输出</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">---</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Feedback</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">执行过程数据</span></span></code></pre></div><p>Goal 表达“要做什么”，Result 表达“最终做成什么样”，Feedback 表达“现在进行到哪里”。</p><p>Feedback 区可以为空。空 Feedback 仍会生成 C++ 消息类型，这是模板化代码生成的结果，但生成出类型不等于存在可用的业务数据。</p><h3 id="_2-2-传输层由五条通信通道组成" tabindex="-1">2.2 传输层由五条通信通道组成 <a class="header-anchor" href="#_2-2-传输层由五条通信通道组成" aria-label="Permalink to &quot;2.2 传输层由五条通信通道组成&quot;">​</a></h3><p>ROS 2 Action 在底层不是一个独立的 DDS 原语，而是 Service 与 Topic 的组合：</p><ul><li><code>send_goal</code> Service：提交 Goal，并获得接受或拒绝响应。</li><li><code>get_result</code> Service：请求某个 Goal 的最终状态和 Result。</li><li><code>cancel_goal</code> Service：请求取消一个或一组 Goal。</li><li><code>feedback</code> Topic：服务端向客户端发布过程反馈。</li><li><code>status</code> Topic：服务端发布 Goal 状态数组。</li></ul><p>这个结构解释了 Action 为什么既像 Service，又能持续反馈和取消。Goal 提交与 Result 获取是分开的，Feedback 也有独立的 Topic 数据流。</p><p><img src="`+n+'" alt="ROS 2 Action 的五条通信通道"></p><h3 id="_2-3-action-适合持续任务" tabindex="-1">2.3 Action 适合持续任务 <a class="header-anchor" href="#_2-3-action-适合持续任务" aria-label="Permalink to &quot;2.3 Action 适合持续任务&quot;">​</a></h3><p>Action 通常用于以下任务：</p><ul><li>机器人导航到目标点。</li><li>机械臂执行一段轨迹。</li><li>底盘跟随一条路径。</li><li>长时间感知或计算任务。</li><li>支持取消、抢占和进度显示的业务任务。</li></ul><p>普通 Service 更适合耗时短、无需过程反馈、无需取消的请求—响应操作。把持续执行任务放进 Service，会让超时、取消和状态观察都变得笨重。</p><h2 id="三、followpath-的三个客户端回调怎样接力" tabindex="-1">三、FollowPath 的三个客户端回调怎样接力 <a class="header-anchor" href="#三、followpath-的三个客户端回调怎样接力" aria-label="Permalink to &quot;三、FollowPath 的三个客户端回调怎样接力&quot;">​</a></h2><h3 id="_3-1-sendfollowpath-负责组装请求" tabindex="-1">3.1 <code>sendFollowPath()</code> 负责组装请求 <a class="header-anchor" href="#_3-1-sendfollowpath-负责组装请求" aria-label="Permalink to &quot;3.1 `sendFollowPath()` 负责组装请求&quot;">​</a></h3><p><code>sendFollowPath(const nav_msgs::msg::Path &amp; path)</code> 是控制链的入口。它先拒绝空路径和空任务，再保存 <code>task_.active_path</code>，把任务状态改为 <code>CONTROLLING</code>。</p><p>随后，它捕获当前任务的 <code>generation</code>，递增 <code>follow_sequence_</code>，并构造：</p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">FollowPath</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::Goal goal;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">goal.path </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> path;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">goal.controller_id </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> control_module_.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">controllerId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">goal.goal_checker_id </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> control_module_.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">goalCheckerId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span></code></pre></div><p>这里的输入是待跟踪 Path，输出不是函数返回值，而是一条异步 Action 数据流。真正的响应会在未来通过三个回调到达。</p><h3 id="_3-2-goal-response-callback-处理接受与拒绝" tabindex="-1">3.2 <code>goal_response_callback</code> 处理接受与拒绝 <a class="header-anchor" href="#_3-2-goal-response-callback-处理接受与拒绝" aria-label="Permalink to &quot;3.2 `goal_response_callback` 处理接受与拒绝&quot;">​</a></h3><p>Goal Response 回调拿到 <code>ClientGoalHandle&lt;FollowPath&gt;::SharedPtr</code>。</p><p>Handle 非空表示 Controller Server 接受了 Goal。代码把它保存到 <code>active_follow_goal_</code>，后续取消、抢占和状态判断都需要这个句柄。</p><p>Handle 为空表示 Goal 被拒绝。此时任务并没有进入正常执行流程，代码直接调用 <code>startRecovery(&quot;控制 Goal 被拒绝&quot;)</code>。</p><p>这个回调只回答“服务端收不收”，不能回答“机器人最终到没到”。</p><h3 id="_3-3-feedback-callback-接收连续运行数据" tabindex="-1">3.3 <code>feedback_callback</code> 接收连续运行数据 <a class="header-anchor" href="#_3-3-feedback-callback-接收连续运行数据" aria-label="Permalink to &quot;3.3 `feedback_callback` 接收连续运行数据&quot;">​</a></h3><p><code>FollowPath.action</code> 的 Feedback 定义了两个字段：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">float32 distance_to_goal</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">float32 speed</span></span></code></pre></div><p>回调把它们写入当前任务：</p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">task_.distance_remaining </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> static_cast&lt;double&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(controller_feedback-&gt;distance_to_goal);</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">current_speed_ </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> controller_feedback-&gt;speed;</span></span></code></pre></div><p>当外层正在执行 <code>FollowFixedPath</code> 时，代码还会新建 <code>FollowFixedPath::Feedback</code>，把剩余距离发布给外部调用者。于是内部 Controller Feedback 被转换成了业务级固定路径 Feedback。</p><p>这说明 Feedback 不是装饰信息。它跨过了两层 Action，成为上游任务系统能够观察的实时进度。</p><h3 id="_3-4-result-callback-负责唯一的最终收口" tabindex="-1">3.4 <code>result_callback</code> 负责唯一的最终收口 <a class="header-anchor" href="#_3-4-result-callback-负责唯一的最终收口" aria-label="Permalink to &quot;3.4 `result_callback` 负责唯一的最终收口&quot;">​</a></h3><p>Result 回调先清理 <code>active_follow_goal_</code>，再检查 <code>WrappedResult.code</code>。</p><p>状态为 <code>SUCCEEDED</code> 时调用 <code>succeedTask()</code>；非成功状态且任务没有处于主动取消流程时，调用 <code>startRecovery()</code>。</p><p><code>FollowPath.action</code> 的 Result 载荷是 <code>std_msgs/Empty</code>。因此，执行是否成功主要由 <code>WrappedResult.code</code> 表达，不能指望从空 Result 消息中读取一个 <code>success</code> 字段。</p><p><img src="'+o+'" alt="FollowPath 三回调数据流"></p><h2 id="四、规划与平滑为什么不需要-feedback-回调" tabindex="-1">四、规划与平滑为什么不需要 Feedback 回调 <a class="header-anchor" href="#四、规划与平滑为什么不需要-feedback-回调" aria-label="Permalink to &quot;四、规划与平滑为什么不需要 Feedback 回调&quot;">​</a></h2><h3 id="_4-1-computepathtopose-返回最终-path" tabindex="-1">4.1 <code>ComputePathToPose</code> 返回最终 Path <a class="header-anchor" href="#_4-1-computepathtopose-返回最终-path" aria-label="Permalink to &quot;4.1 `ComputePathToPose` 返回最终 Path&quot;">​</a></h3><p>单点规划 Goal 包含终点、可选起点、规划器 ID 和 <code>use_start</code>。当前 Navigator 设置 <code>use_start=false</code>，让 Planner Server 通过 TF 获取机器人当前位置。</p><p>Result 包含：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">nav_msgs/Path path</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">builtin_interfaces/Duration planning_time</span></span></code></pre></div><p>调用方真正需要的产物是完整 Path。Goal 被接受后，等待一次 Result 就能推进状态机。</p><h3 id="_4-2-computepaththroughposes-语义相同" tabindex="-1">4.2 <code>ComputePathThroughPoses</code> 语义相同 <a class="header-anchor" href="#_4-2-computepaththroughposes-语义相同" aria-label="Permalink to &quot;4.2 `ComputePathThroughPoses` 语义相同&quot;">​</a></h3><p>多点规划把单个目标换成目标数组，Result 仍然是 Path 与规划耗时。当前接口没有定义“已经处理了几个目标”或“搜索完成比例”，所以没有可以消费的中间反馈。</p><h3 id="_4-3-smoothpath-也是结果驱动" tabindex="-1">4.3 <code>SmoothPath</code> 也是结果驱动 <a class="header-anchor" href="#_4-3-smoothpath-也是结果驱动" aria-label="Permalink to &quot;4.3 `SmoothPath` 也是结果驱动&quot;">​</a></h3><p>平滑 Goal 输入原始 Path、平滑器 ID、最长平滑时间和碰撞检查开关。Result 返回：</p><ul><li>平滑后的 Path。</li><li>实际平滑耗时。</li><li><code>was_completed</code> 完成标志。</li></ul><p>当前 Navigator 在成功且 Path 非空时调用 <code>sendFollowPath()</code>；失败时回退 <code>pending_raw_path_</code>。这同样是“请求一个最终产物”的流水线。</p><h3 id="_4-4-空-feedback-类型不等于需要空回调" tabindex="-1">4.4 空 Feedback 类型不等于需要空回调 <a class="header-anchor" href="#_4-4-空-feedback-类型不等于需要空回调" aria-label="Permalink to &quot;4.4 空 Feedback 类型不等于需要空回调&quot;">​</a></h3><p>三个 <code>.action</code> 文件都保留 Feedback 分隔区，但区内没有字段。ROS 2 仍会生成 <code>ActionT::Feedback</code>，客户端也仍然可以写一个类型正确的 <code>feedback_callback</code>。</p><p>但服务端没有业务数据可以填充，当前 Planner Server 和 Smoother Server 也不需要周期发布空消息。所以不注册回调更清楚地表达了接口事实：这个 Action 的中间过程不是公共协议的一部分。</p><p><img src="'+c+'" alt="规划与平滑的两回调流水线"></p><h2 id="五、常规-action-client-会用到哪些函数" tabindex="-1">五、常规 Action Client 会用到哪些函数 <a class="header-anchor" href="#五、常规-action-client-会用到哪些函数" aria-label="Permalink to &quot;五、常规 Action Client 会用到哪些函数&quot;">​</a></h2><h3 id="_5-1-rclcpp-action-create-client" tabindex="-1">5.1 <code>rclcpp_action::create_client()</code> <a class="header-anchor" href="#_5-1-rclcpp-action-create-client" aria-label="Permalink to &quot;5.1 `rclcpp_action::create_client()`&quot;">​</a></h3><p>创建并把 Action Client 加入节点：</p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">client_ </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> rclcpp_action</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">create_client</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ActionType</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;(node, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;action_name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>客户端创建成功不代表服务端已经启动。Action 名称和 Action 类型必须与服务端一致。</p><h3 id="_5-2-wait-for-action-server" tabindex="-1">5.2 <code>wait_for_action_server()</code> <a class="header-anchor" href="#_5-2-wait-for-action-server" aria-label="Permalink to &quot;5.2 `wait_for_action_server()`&quot;">​</a></h3><p>在发送 Goal 前等待服务端可用：</p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">client_-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wait_for_action_server</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(timeout)) {</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>它只检查 Action Server 的通信端点是否就绪，不会验证某个 Goal 一定会被接受。</p><h3 id="_5-3-sendgoaloptions" tabindex="-1">5.3 <code>SendGoalOptions</code> <a class="header-anchor" href="#_5-3-sendgoaloptions" aria-label="Permalink to &quot;5.3 `SendGoalOptions`&quot;">​</a></h3><p><code>SendGoalOptions</code> 是发送 Goal 时的回调配置：</p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">typename</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> rclcpp_action</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Client</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ActionType</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SendGoalOptions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> options;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">options.goal_response_callback </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ...;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">options.feedback_callback </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ...;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">options.result_callback </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ...;</span></span></code></pre></div><p>三个成员默认都是 <code>nullptr</code>。是否设置，取决于调用方准备怎样消费异步结果。</p><h3 id="_5-4-async-send-goal" tabindex="-1">5.4 <code>async_send_goal()</code> <a class="header-anchor" href="#_5-4-async-send-goal" aria-label="Permalink to &quot;5.4 `async_send_goal()`&quot;">​</a></h3><p>发送 Goal：</p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">auto</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> future </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> client_-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">async_send_goal</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(goal, options);</span></span></code></pre></div><p>函数返回一个共享 Future。服务端接受 Goal 时，Future 得到有效 Goal Handle；拒绝时得到空 Handle。如果配置了 Goal Response 回调，同样的接受／拒绝结果会通过回调通知调用方。</p><p><code>async_send_goal()</code> 不会等任务执行完才返回。它只启动异步交互。</p><h3 id="_5-5-async-get-result" tabindex="-1">5.5 <code>async_get_result()</code> <a class="header-anchor" href="#_5-5-async-get-result" aria-label="Permalink to &quot;5.5 `async_get_result()`&quot;">​</a></h3><p>调用方可以通过 Goal Handle 主动请求最终结果：</p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">auto</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> result_future </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> client_-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">async_get_result</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(goal_handle);</span></span></code></pre></div><p>如果发送 Goal 时已经设置 <code>result_callback</code>，通常不需要再额外组织一条等待 Future 的业务链。两种风格应当按状态机结构选择，避免同一任务出现两套终态处理逻辑。</p><h3 id="_5-6-async-cancel-goal" tabindex="-1">5.6 <code>async_cancel_goal()</code> <a class="header-anchor" href="#_5-6-async-cancel-goal" aria-label="Permalink to &quot;5.6 `async_cancel_goal()`&quot;">​</a></h3><p>取消指定 Goal：</p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">client_-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">async_cancel_goal</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(goal_handle);</span></span></code></pre></div><p>返回的 Cancel Response 只表示服务端是否接受“尝试取消”的请求，不表示任务已经停止，也不表示客户端已经收到 <code>CANCELED</code> Result。</p><h3 id="_5-7-批量取消函数" tabindex="-1">5.7 批量取消函数 <a class="header-anchor" href="#_5-7-批量取消函数" aria-label="Permalink to &quot;5.7 批量取消函数&quot;">​</a></h3><p>客户端还提供：</p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">client_-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">async_cancel_all_goals</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">client_-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">async_cancel_goals_before</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(stamp);</span></span></code></pre></div><p>前者请求取消当前 Action Server 的全部 Goal，后者按时间戳取消一组 Goal。导航系统通常更适合持有明确 Goal Handle 并定点取消，避免影响不属于当前任务的 Goal。</p><h3 id="_5-8-client-goal-handle" tabindex="-1">5.8 Client Goal Handle <a class="header-anchor" href="#_5-8-client-goal-handle" aria-label="Permalink to &quot;5.8 Client Goal Handle&quot;">​</a></h3><p>客户端 Goal Handle 表示一个已经被服务端接受的具体 Goal。常见用途包括：</p><ul><li>取得 Goal UUID。</li><li>查询本地已知状态。</li><li>请求最终 Result。</li><li>发起取消。</li><li>把 Feedback 和 Result 与特定 Goal 对齐。</li></ul><p>Handle 是后续控制权的凭证，所以当前代码会在 Goal Response 回调中保存它，在 Result 回调中释放它。</p><h2 id="六、三个客户端回调的准确语义" tabindex="-1">六、三个客户端回调的准确语义 <a class="header-anchor" href="#六、三个客户端回调的准确语义" aria-label="Permalink to &quot;六、三个客户端回调的准确语义&quot;">​</a></h2><h3 id="_6-1-goal-response-callback" tabindex="-1">6.1 Goal Response Callback <a class="header-anchor" href="#_6-1-goal-response-callback" aria-label="Permalink to &quot;6.1 Goal Response Callback&quot;">​</a></h3><p>典型签名为：</p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">void</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> callback</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">GoalHandle</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SharedPtr</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> goal_handle</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>它可能只调用一次。Handle 非空表示接受，空 Handle 表示拒绝。</p><p>Goal 被拒绝后不会进入正常执行状态，调用方必须在这里完成拒绝处理，不能假设未来还会收到一个普通 Result 回调来兜底。</p><h3 id="_6-2-feedback-callback" tabindex="-1">6.2 Feedback Callback <a class="header-anchor" href="#_6-2-feedback-callback" aria-label="Permalink to &quot;6.2 Feedback Callback&quot;">​</a></h3><p>典型签名为：</p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">void</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> callback</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">GoalHandle</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SharedPtr</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> goal_handle</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">std</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">shared_ptr</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> ActionType</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Feedback</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt; </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">feedback</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>它可能一次都不调用，也可能调用很多次。回调适合更新进度、速度、剩余时间和 UI，不适合决定任务的最终成功。</p><p>Feedback 与取消、Result 可能在多线程执行器中靠得很近。回调需要确认 Goal 身份和任务当前性。</p><h3 id="_6-3-result-callback" tabindex="-1">6.3 Result Callback <a class="header-anchor" href="#_6-3-result-callback" aria-label="Permalink to &quot;6.3 Result Callback&quot;">​</a></h3><p>典型签名为：</p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">void</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> callback</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> GoalHandle</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">WrappedResult</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &amp;</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> result</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p><code>WrappedResult</code> 同时携带 Goal ID、结果码和 <code>.action</code> 定义的 Result 载荷。常见结果码包括：</p><ul><li><code>SUCCEEDED</code>：正常成功。</li><li><code>ABORTED</code>：服务端执行失败。</li><li><code>CANCELED</code>：任务完成取消收口。</li><li><code>UNKNOWN</code>：客户端无法识别终态。</li></ul><p>代码需要同时核对结果码、Result 指针和业务字段。仅检查其中一项，容易把传输状态和业务状态混在一起。</p><h2 id="七、常规-action-server-会用到哪些函数" tabindex="-1">七、常规 Action Server 会用到哪些函数 <a class="header-anchor" href="#七、常规-action-server-会用到哪些函数" aria-label="Permalink to &quot;七、常规 Action Server 会用到哪些函数&quot;">​</a></h2><h3 id="_7-1-rclcpp-action-create-server" tabindex="-1">7.1 <code>rclcpp_action::create_server()</code> <a class="header-anchor" href="#_7-1-rclcpp-action-create-server" aria-label="Permalink to &quot;7.1 `rclcpp_action::create_server()`&quot;">​</a></h3><p>创建 Action Server 时必须提供三个入口：</p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">server_ </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> rclcpp_action</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">create_server</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ActionType</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;(</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  node,</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;action_name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  handle_goal,</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  handle_cancel,</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  handle_accepted);</span></span></code></pre></div><p>这里的三个服务端入口与客户端的三个回调不是一一对应关系。</p><p>客户端回调描述“客户端准备消费哪些返回数据”；服务端入口描述“服务端怎样接收 Goal、处理取消并启动执行”。</p><h3 id="_7-2-handle-goal" tabindex="-1">7.2 <code>handle_goal</code> <a class="header-anchor" href="#_7-2-handle-goal" aria-label="Permalink to &quot;7.2 `handle_goal`&quot;">​</a></h3><p>Goal 回调的典型签名为：</p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rclcpp_action</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">GoalResponse</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> callback</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  const</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> rclcpp_action</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">GoalUUID</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &amp;</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> uuid</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  std</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">shared_ptr</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> ActionType</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Goal</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt; </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">goal</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>它适合执行快速校验：</p><ul><li>节点是否激活。</li><li>当前模式是否允许此 Action。</li><li>Goal 字段是否完整。</li><li>数值、坐标系和枚举是否合法。</li><li>当前资源是否允许接受新任务。</li></ul><p>返回值包括 <code>REJECT</code>、<code>ACCEPT_AND_EXECUTE</code> 和 <code>ACCEPT_AND_DEFER</code>。</p><p><code>ACCEPT_AND_EXECUTE</code> 表示接受后立即进入执行态；<code>ACCEPT_AND_DEFER</code> 表示先接受，稍后由代码调用 Goal Handle 的 <code>execute()</code>。</p><h3 id="_7-3-handle-cancel" tabindex="-1">7.3 <code>handle_cancel</code> <a class="header-anchor" href="#_7-3-handle-cancel" aria-label="Permalink to &quot;7.3 `handle_cancel`&quot;">​</a></h3><p>Cancel 回调的典型签名为：</p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rclcpp_action</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">CancelResponse</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> callback</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">std</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">shared_ptr</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ServerGoalHandle</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt; </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">goal_handle</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>它返回 <code>ACCEPT</code> 或 <code>REJECT</code>。<code>ACCEPT</code> 的准确含义是“服务端愿意尝试取消”，真正停止控制、释放资源和生成取消 Result 仍由执行逻辑完成。</p><p>当前固定路径实现只设置 <code>cancel_requested_</code>，由统一监控逻辑执行下游取消和任务复位。这避免了在 Cancel 回调中重入复杂状态机。</p><h3 id="_7-4-handle-accepted" tabindex="-1">7.4 <code>handle_accepted</code> <a class="header-anchor" href="#_7-4-handle-accepted" aria-label="Permalink to &quot;7.4 `handle_accepted`&quot;">​</a></h3><p>Accepted 回调在 Goal 被接受后获得 <code>ServerGoalHandle</code>。它应该快速保存句柄，并把耗时工作派发到工作线程、定时器或状态机。</p><p>ROS 2 Humble 的 <code>rclcpp_action::Server</code> 头文件明确要求 Goal、Cancel 和 Accepted 回调保持非阻塞。原因是这些入口由 Executor 调度，长时间等待会占用执行器线程，并延迟其他 Topic、Service、Timer 和 Action 回调。</p><h3 id="_7-5-publish-feedback" tabindex="-1">7.5 <code>publish_feedback()</code> <a class="header-anchor" href="#_7-5-publish-feedback" aria-label="Permalink to &quot;7.5 `publish_feedback()`&quot;">​</a></h3><p>服务端在 Goal 执行期间发布反馈：</p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">auto</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> feedback </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> std</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make_shared</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ActionType</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Feedback</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;();</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">goal_handle-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">publish_feedback</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(feedback);</span></span></code></pre></div><p>反馈应该有稳定语义，并控制发布频率。高频发布不等于信息更多，反而可能增加 DDS、Executor 和日志压力。</p><h3 id="_7-6-succeed-、abort-与-canceled" tabindex="-1">7.6 <code>succeed()</code>、<code>abort()</code> 与 <code>canceled()</code> <a class="header-anchor" href="#_7-6-succeed-、abort-与-canceled" aria-label="Permalink to &quot;7.6 `succeed()`、`abort()` 与 `canceled()`&quot;">​</a></h3><p>服务端通过 Goal Handle 的终态函数结束任务：</p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">goal_handle-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">succeed</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(result);</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">goal_handle-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">abort</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(result);</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">goal_handle-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">canceled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(result);</span></span></code></pre></div><p>三者分别表示成功、执行失败和取消完成。一个 Goal 进入终态后，不应继续发布 Feedback，也不应再次调用其他终态函数。</p><h3 id="_7-7-execute" tabindex="-1">7.7 <code>execute()</code> <a class="header-anchor" href="#_7-7-execute" aria-label="Permalink to &quot;7.7 `execute()`&quot;">​</a></h3><p>Goal 通过 <code>ACCEPT_AND_DEFER</code> 接受时，可以在资源就绪后调用：</p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">goal_handle-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">execute</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span></code></pre></div><p>这适合需要排队、串行化资源或等待调度窗口的服务端。直接使用 <code>ACCEPT_AND_EXECUTE</code> 时不需要额外调用。</p><p><img src="'+p+'" alt="Action Server 的入口与终态"></p><h2 id="八、当前固定路径-action-展示了怎样的服务端设计" tabindex="-1">八、当前固定路径 Action 展示了怎样的服务端设计 <a class="header-anchor" href="#八、当前固定路径-action-展示了怎样的服务端设计" aria-label="Permalink to &quot;八、当前固定路径 Action 展示了怎样的服务端设计&quot;">​</a></h2><h3 id="_8-1-handlefixedpathgoal-做快速结构校验" tabindex="-1">8.1 <code>handleFixedPathGoal()</code> 做快速结构校验 <a class="header-anchor" href="#_8-1-handlefixedpathgoal-做快速结构校验" aria-label="Permalink to &quot;8.1 `handleFixedPathGoal()` 做快速结构校验&quot;">​</a></h3><p>它检查运行模式、Lifecycle 激活状态、路径点数量、顶层坐标系、有限坐标和四元数有效性。结构错误直接返回 <code>REJECT</code>。</p><p>这类检查适合放在 Goal 回调，因为它们不需要等待外部系统。</p><h3 id="_8-2-handlefixedpathcancel-只设置取消请求" tabindex="-1">8.2 <code>handleFixedPathCancel()</code> 只设置取消请求 <a class="header-anchor" href="#_8-2-handlefixedpathcancel-只设置取消请求" aria-label="Permalink to &quot;8.2 `handleFixedPathCancel()` 只设置取消请求&quot;">​</a></h3><p>当前代码确认 Goal 是否为活动固定路径 Goal，然后设置 <code>cancel_requested_</code>，最后返回 <code>CancelResponse::ACCEPT</code>。</p><p>它没有在 Action 回调里同步取消下游 FollowPath、清理 Costmap 或发布终态。这种分层避免 Cancel 回调承担过多职责。</p><h3 id="_8-3-handlefixedpathaccepted-启动内部-followpath" tabindex="-1">8.3 <code>handleFixedPathAccepted()</code> 启动内部 FollowPath <a class="header-anchor" href="#_8-3-handlefixedpathaccepted-启动内部-followpath" aria-label="Permalink to &quot;8.3 `handleFixedPathAccepted()` 启动内部 FollowPath&quot;">​</a></h3><p>Accepted 回调会完成 Path 坐标转换、等待 FollowPath Server、抢占旧任务、建立新任务状态并调用 <code>sendFollowPath()</code>。</p><p>业务上，这形成了外层 <code>FollowFixedPath</code> Server 到内层 <code>FollowPath</code> Client 的桥接。</p><p>工程上需要看到一个边界：TF 转换会遍历路径，<code>wait_for_action_server()</code> 也可能等待 <code>server_timeout_</code>。它们让 Accepted 回调比“保存句柄并立即派发”更重。</p><p>多线程 Executor 可以降低单个线程阻塞的影响，但不能把阻塞本身变成无成本。如果固定路径点很多，或下游 Server 经常未就绪，更稳妥的结构是把准备和等待逻辑交给任务状态机，再由 Accepted 回调快速返回。</p><h2 id="九、异步-action-为什么必须过滤旧回调" tabindex="-1">九、异步 Action 为什么必须过滤旧回调 <a class="header-anchor" href="#九、异步-action-为什么必须过滤旧回调" aria-label="Permalink to &quot;九、异步 Action 为什么必须过滤旧回调&quot;">​</a></h2><h3 id="_9-1-回调到达顺序不等于任务创建顺序" tabindex="-1">9.1 回调到达顺序不等于任务创建顺序 <a class="header-anchor" href="#_9-1-回调到达顺序不等于任务创建顺序" aria-label="Permalink to &quot;9.1 回调到达顺序不等于任务创建顺序&quot;">​</a></h3><p>导航系统会重规划、抢占、取消和恢复。Goal A 发出后，Goal B 可能已经替代它，但 Goal A 的 Feedback 或 Result 仍可能晚到。</p><p>如果旧 Result 不经检查直接调用 <code>succeedTask()</code>，新任务可能被错误结束；如果旧规划结果直接覆盖当前 Path，机器人可能沿上一条任务路径运动。</p><h3 id="_9-2-generation-隔离不同外层任务" tabindex="-1">9.2 <code>generation</code> 隔离不同外层任务 <a class="header-anchor" href="#_9-2-generation-隔离不同外层任务" aria-label="Permalink to &quot;9.2 `generation` 隔离不同外层任务&quot;">​</a></h3><p>每次外层任务变化，<code>task_.generation</code> 都会更新。回调捕获发送 Goal 时的 generation，并与当前任务比较。</p><p>它回答的是：</p><blockquote><p>这个回调还属于当前导航任务吗？</p></blockquote><h3 id="_9-3-sequence-隔离同一任务的多次请求" tabindex="-1">9.3 <code>sequence</code> 隔离同一任务的多次请求 <a class="header-anchor" href="#_9-3-sequence-隔离同一任务的多次请求" aria-label="Permalink to &quot;9.3 `sequence` 隔离同一任务的多次请求&quot;">​</a></h3><p>同一个外层任务可能周期重规划，也可能多次更新 FollowPath。</p><p><code>plan_sequence_</code> 区分同一任务内的多次规划；<code>follow_sequence_</code> 区分多次控制 Goal。它回答的是：</p><blockquote><p>这个回调还是当前任务里最新的一次下游请求吗？</p></blockquote><h3 id="_9-4-两层标识共同构成当前性门禁" tabindex="-1">9.4 两层标识共同构成当前性门禁 <a class="header-anchor" href="#_9-4-两层标识共同构成当前性门禁" aria-label="Permalink to &quot;9.4 两层标识共同构成当前性门禁&quot;">​</a></h3><p><code>isCurrentPlan()</code> 和 <code>isCurrentFollow()</code> 同时比较任务代次与请求序号。只有两个值都匹配，回调才能修改共享状态。</p><p>这是一种轻量的逻辑失效机制。它不要求旧网络消息立即消失，而是保证旧消息到达后没有写权限。</p><p><img src="'+h+'" alt="异步旧回调隔离机制"></p><h2 id="十、怎样决定一个-action-是否需要-feedback" tabindex="-1">十、怎样决定一个 Action 是否需要 Feedback <a class="header-anchor" href="#十、怎样决定一个-action-是否需要-feedback" aria-label="Permalink to &quot;十、怎样决定一个 Action 是否需要 Feedback&quot;">​</a></h2><h3 id="_10-1-适合定义-feedback-的任务" tabindex="-1">10.1 适合定义 Feedback 的任务 <a class="header-anchor" href="#_10-1-适合定义-feedback-的任务" aria-label="Permalink to &quot;10.1 适合定义 Feedback 的任务&quot;">​</a></h3><p>Feedback 值得进入公共接口时，通常满足以下条件：</p><ul><li>任务持续时间足以让调用方感知等待。</li><li>中间状态对上层调度或用户有价值。</li><li>数据可以稳定解释，而不是插件私有调试变量。</li><li>服务端能够以合理频率持续产生数据。</li><li>调用方会用它做展示、监控、估时或控制决策。</li></ul><p><code>FollowPath</code> 的剩余距离与速度符合这些条件。</p><h3 id="_10-2-不适合为了对称增加-feedback" tabindex="-1">10.2 不适合为了对称增加 Feedback <a class="header-anchor" href="#_10-2-不适合为了对称增加-feedback" aria-label="Permalink to &quot;10.2 不适合为了对称增加 Feedback&quot;">​</a></h3><p>以下情况通常不需要 Feedback：</p><ul><li>任务很短，Result 很快到达。</li><li>中间值不稳定，容易被误解成完成比例。</li><li>不同插件无法提供一致语义。</li><li>调用方收到后不会采取任何动作。</li><li>只能发布空消息或重复陈旧数据。</li></ul><p>当前 ComputePath 和 SmoothPath 的接口选择就是结果驱动，而不是过程驱动。</p><h3 id="_10-3-新增-feedback-应从协议开始" tabindex="-1">10.3 新增 Feedback 应从协议开始 <a class="header-anchor" href="#_10-3-新增-feedback-应从协议开始" aria-label="Permalink to &quot;10.3 新增 Feedback 应从协议开始&quot;">​</a></h3><p>如果未来希望规划过程可观测，应先修改 <code>.action</code>，定义真正可消费的数据，例如：</p><ul><li>已展开搜索节点数。</li><li>当前最优路径代价。</li><li>搜索或平滑迭代次数。</li><li>已消耗时间。</li><li>可解释的阶段状态。</li></ul><p>随后由服务端实际调用 <code>publish_feedback()</code>，客户端再注册 <code>feedback_callback</code>。只改单侧客户端没有意义。</p><h3 id="_10-4-feedback-应限频且不拥有终态" tabindex="-1">10.4 Feedback 应限频且不拥有终态 <a class="header-anchor" href="#_10-4-feedback-应限频且不拥有终态" aria-label="Permalink to &quot;10.4 Feedback 应限频且不拥有终态&quot;">​</a></h3><p>Feedback 可以帮助估计任务进度，但不应替代 Result。即使剩余距离显示为零，也可能仍需满足 Goal Checker、姿态误差或停止条件。</p><p>最终状态只能由 <code>succeed()</code>、<code>abort()</code> 或 <code>canceled()</code> 产生，并在客户端 Result 回调中统一处理。</p><h2 id="十一、最容易混淆的-action-语义" tabindex="-1">十一、最容易混淆的 Action 语义 <a class="header-anchor" href="#十一、最容易混淆的-action-语义" aria-label="Permalink to &quot;十一、最容易混淆的 Action 语义&quot;">​</a></h2><h3 id="_11-1-goal-被接受不等于任务成功" tabindex="-1">11.1 Goal 被接受不等于任务成功 <a class="header-anchor" href="#_11-1-goal-被接受不等于任务成功" aria-label="Permalink to &quot;11.1 Goal 被接受不等于任务成功&quot;">​</a></h3><p>Goal Response 只表示服务端愿意执行。路径可能在后续跟踪中遇到障碍、控制失败或被主动取消。</p><h3 id="_11-2-接受取消不等于已经取消" tabindex="-1">11.2 接受取消不等于已经取消 <a class="header-anchor" href="#_11-2-接受取消不等于已经取消" aria-label="Permalink to &quot;11.2 接受取消不等于已经取消&quot;">​</a></h3><p>Cancel 回调返回 <code>ACCEPT</code> 后，执行逻辑仍需真正停止任务，并调用 <code>canceled(result)</code>。客户端应以最终 <code>CANCELED</code> Result 作为取消完成依据。</p><h3 id="_11-3-有-feedback-类型不等于有反馈字段" tabindex="-1">11.3 有 Feedback 类型不等于有反馈字段 <a class="header-anchor" href="#_11-3-有-feedback-类型不等于有反馈字段" aria-label="Permalink to &quot;11.3 有 Feedback 类型不等于有反馈字段&quot;">​</a></h3><p>空 Feedback 仍有生成类型，但没有可传递的业务数据。接口定义、服务端发布行为和客户端消费逻辑必须同时成立，Feedback 链路才有意义。</p><h3 id="_11-4-result-载荷不等于-resultcode" tabindex="-1">11.4 Result 载荷不等于 ResultCode <a class="header-anchor" href="#_11-4-result-载荷不等于-resultcode" aria-label="Permalink to &quot;11.4 Result 载荷不等于 ResultCode&quot;">​</a></h3><p><code>.action</code> 的 Result 是业务载荷，<code>WrappedResult.code</code> 是 Action 终态。<code>FollowPath</code> 的载荷为空，但仍能通过 <code>SUCCEEDED</code>、<code>ABORTED</code> 和 <code>CANCELED</code> 清楚表达结果。</p><h3 id="_11-5-客户端三个回调不等于服务端三个入口" tabindex="-1">11.5 客户端三个回调不等于服务端三个入口 <a class="header-anchor" href="#_11-5-客户端三个回调不等于服务端三个入口" aria-label="Permalink to &quot;11.5 客户端三个回调不等于服务端三个入口&quot;">​</a></h3><p>客户端的 Goal Response、Feedback、Result 是返回数据消费点。</p><p>服务端的 Goal、Cancel、Accepted 是请求接收和执行控制点。两边都恰好出现“三个”，但职责完全不同，不能按名称或数量机械对应。</p><h2 id="十二、回到最初问题" tabindex="-1">十二、回到最初问题 <a class="header-anchor" href="#十二、回到最初问题" aria-label="Permalink to &quot;十二、回到最初问题&quot;">​</a></h2><h3 id="_12-1-navigator-control-cpp-的三个回调都不可替代" tabindex="-1">12.1 <code>navigator_control.cpp</code> 的三个回调都不可替代 <a class="header-anchor" href="#_12-1-navigator-control-cpp-的三个回调都不可替代" aria-label="Permalink to &quot;12.1 `navigator_control.cpp` 的三个回调都不可替代&quot;">​</a></h3><p>它需要处理 Goal 接收、持续控制反馈和最终终态，还要把内部 FollowPath Feedback 转成外层 FollowFixedPath Feedback。</p><h3 id="_12-2-navigator-planning-cpp-的两个回调已经完整" tabindex="-1">12.2 <code>navigator_planning.cpp</code> 的两个回调已经完整 <a class="header-anchor" href="#_12-2-navigator-planning-cpp-的两个回调已经完整" aria-label="Permalink to &quot;12.2 `navigator_planning.cpp` 的两个回调已经完整&quot;">​</a></h3><p>规划和平滑 Action 的公共协议只承诺 Goal Response 与最终 Path，没有定义中间反馈字段。省略 <code>feedback_callback</code> 不是缺失，而是忠实反映接口。</p><h3 id="_12-3-最终设计原则" tabindex="-1">12.3 最终设计原则 <a class="header-anchor" href="#_12-3-最终设计原则" aria-label="Permalink to &quot;12.3 最终设计原则&quot;">​</a></h3><p>ROS 2 Action 的回调设计可以归结为一句话：</p><blockquote><p>按任务语义和真实数据流注册回调，不按结构体提供了多少槽位追求形式对称。</p></blockquote><p>持续执行的任务需要可观察、可取消和可收口；有界计算任务如果只产生最终产物，就让 Result 承担结果语义。当异步 Goal 可能重叠时，再用 Goal Handle、任务代次和请求序号守住共享状态边界。</p><p>理解这条原则后，Action 就不再是“比 Service 多一个 Feedback”的接口，而是一套围绕长任务生命周期设计的完整通信协议。</p>',226)])])}const F=e(d,[["render",r]]);export{y as __pageData,F as default};
